const $=id=>document.getElementById(id);
let worker,ready=false,busy=false,requests=new Map(),serial=0,chatHistory=[],lastQuestion='',lastScope='',answerWriter;
const norm=normalize;
const stopWords=new Set('que qui quien quin quina qual cual cuales com como quan cuando donde por per para una uno unos unes las los les els del amb con sobre aquest aquesta este esta esto hay te tiene fue son era sus mas mes molt muy ara ahora dime saber sabes pots puedes el la de i y en a un se es su lo al em me mi tu'.split(' '));
function tokens(s){return norm(s).match(/[a-z0-9]+/g)?.filter(x=>x.length>2&&!stopWords.has(x))||[]}
function retrieve(q,pool){let tq=tokens(q),nq=norm(q);let intent=/franqu|dictadur/.test(nq)?'franqu':/colonial|esclav|trata|trafic/.test(nq)?'colonial':/verific|pend|duda|dubte|discrep/.test(nq)?'verif':/actual|hoy|avui|retir|diallo/.test(nq)?'actual':/fuente|font|bibliograf/.test(nq)?'fonts':/autor|inaugur|constru|ubic|material/.test(nq)?'ident':/historia|origen/.test(nq)?'sintesi':'';
return pool.flatMap(r=>r.paragraphs.map((text,i)=>{const words=tokens(text),heading=norm(text.split('. ')[0]);let score=tq.reduce((s,x)=>s+(words.some(w=>w===x||x.length>4&&w.startsWith(x))?1:0),0);if(intent==='franqu'&&heading.includes('franqu')||intent==='colonial'&&heading.includes('colonial')||intent==='actual'&&heading.includes('actual')||intent==='ident'&&heading.includes('ident')||intent==='sintesi'&&/sintesi/.test(heading)||intent==='fonts'&&/fuente|font/.test(heading))score+=4;if(intent==='verif'&&/verif\.|no document|sin document|sense document|gairebe no|casi no/.test(norm(text)))score+=3;return{r,i,text,score}})).filter(h=>h.score>=(tq.length>3?2:1)).sort((a,b)=>b.score-a.score).slice(0,4)}
function message(text,type='bot'){const d=document.createElement('div');d.className='chat-message '+type;d.textContent=text;$('chatlog').append(d);if(type==='bot'&&text)window.attachListen(d,text);$('chatlog').scrollTop=$('chatlog').scrollHeight;return d}
function scope(){$('chatscope').textContent=current?current.name:t('chatScopeAll');$('chatinput').placeholder=current?t('chatPlaceholderPlace'):t('chatPlaceholder')}
window.updateChatScope=scope;
window.openAtlasChat=()=>{$('chatpanel').hidden=false;scope();$('chatinput').focus({preventScroll:true})};$('chatinput').onfocus=()=>{$('chatpanel').hidden=false;scope()};$('chatcollapse').onclick=()=>{$('chatpanel').hidden=true};
function clear(){if(busy)return;$('chatlog').replaceChildren();chatHistory=[];lastQuestion='';lastScope='';message(t('chatHello'));scope()}
$('chatprompt').querySelectorAll('button').forEach(b=>b.onclick=()=>{$('chatinput').value=b.textContent;$('chatform').requestSubmit()});
function rpc(type,payload={},onDelta){return new Promise((resolve,reject)=>{const id=++serial;const timer=setTimeout(()=>{requests.delete(id);reject(Error('timeout'))},type==='load'?600000:180000);requests.set(id,{resolve:v=>{clearTimeout(timer);resolve(v)},reject:e=>{clearTimeout(timer);reject(e)},onDelta});worker.postMessage({id,type,...payload})})}
$('loadlocal').onclick=async()=>{if(ready)return;const b=$('loadlocal');b.disabled=true;try{if(!navigator.gpu||!await navigator.gpu.requestAdapter())throw Error('WebGPU');worker=new Worker('chat-worker.js',{type:'module'});worker.onmessage=e=>{const m=e.data;if(m.type==='progress'){$('chatstatus').textContent=t('chatDownload');return}const r=requests.get(m.id);if(r){if(m.type==='delta'){r.onDelta?.(m.text);return}requests.delete(m.id);m.error?r.reject(Error(m.error)):r.resolve(m.result)}};worker.onerror=()=>{for(const r of requests.values())r.reject(Error('worker'));requests.clear()};$('chatstatus').textContent=t('chatDownload');await rpc('load');ready=true;b.textContent=t('chatReady');$('chatstatus').textContent=t('chatLocalStatus')}catch{worker?.terminate();ready=false;b.disabled=false;$('chatstatus').textContent=t('chatUnavailable')}};
$('chatform').onsubmit=async e=>{e.preventDefault();if(busy)return;const q=$('chatinput').value.trim();if(!q)return;window.openAtlasChat();message(q,'user');$('chatinput').value='';if(!records.length){message(t('chatLoadingData'));return}const selected=current,named=records.filter(r=>tokens(r.name).some(x=>x.length>3&&tokens(q).includes(x))),pool=named.length?named:selected?[selected]:records;const scopeKey=lang+':'+pool.map(r=>r.id).join(',');if(scopeKey!==lastScope){chatHistory=[];lastQuestion='';lastScope=scopeKey}
if(!ready){message(t('chatNeedsModel'));$('chatinput').value=q;$('localsettings').open=true;return}
if(/^(hola|buenas|bon dia|gracies|gracias|muchas gracias)[!. ]*$/i.test(norm(q))){message(/graci/.test(norm(q))?t('chatThanks'):t('chatGreeting'));return}
let hits=retrieve(q,pool);if(lastQuestion&&(/explica|entiend|enten|mes|mas|eso|aixo|aquell|por que|per que|resum|sencill|continua|ejemplo|exemple/.test(norm(q))||tokens(q).length<2))hits=retrieve(lastQuestion+' '+q,pool);if(!hits.length&&/cuenta|explica|present|resum|interes|importan|empiez|empez|comenc|ayuda|ajuda|recom/.test(norm(q)))hits=pool.slice(0,2).flatMap(r=>r.paragraphs.slice(0,2).map((text,i)=>({r,i,text})));
busy=true;$('chatsend').disabled=true;document.querySelectorAll('[data-lang]').forEach(b=>b.disabled=true);const pending=message('');
try{if(!hits.length){pending.textContent=t('chatNoEvidence');window.attachListen(pending,pending.textContent);return}const passages=[];let size=0;for(const h of hits){if(size+h.text.length>7500)continue;passages.push(h);size+=h.text.length;if(passages.length===3)break}if(!passages.length){pending.textContent=t('chatTooLong');return}answerWriter=typewriter(pending,{speed:3,onUpdate:()=>{const log=$('chatlog');if(log.scrollHeight-log.scrollTop-log.clientHeight<120)log.scrollTop=log.scrollHeight}});const result=await rpc('answer',{question:q,language:lang,passages:passages.map(h=>({text:h.text,place:h.r.name})),history:chatHistory},delta=>{answerWriter.append(delta)});if(typeof result!=='string'||!result.trim())throw Error('empty');await answerWriter.finish();window.attachListen(pending,result);chatHistory.push({role:'user',content:q},{role:'assistant',content:result});chatHistory=chatHistory.slice(-4);lastQuestion=q;
const refs=document.createElement('details'),title=document.createElement('summary');title.textContent=t('chatSourceLink');refs.append(title);passages.forEach((h,i)=>{const b=document.createElement('button');b.textContent='['+(i+1)+'] '+h.r.name+' · '+h.text.split('. ')[0];b.onclick=()=>{openPlace(h.r);window.showHistory();$('chatpanel').hidden=true};refs.append(b)});pending.append(refs)
}catch{answerWriter?.cancel();pending.textContent=t('chatError')}finally{busy=false;$('chatsend').disabled=false;document.querySelectorAll('[data-lang]').forEach(b=>b.disabled=false);}};
window.addEventListener('atlaslanguage',()=>{clear();$('chatstatus').textContent=ready?t('chatLocalStatus'):t('chatInitialStatus');$('loadlocal').textContent=ready?t('chatReady'):t('loadLocal')});clear();scope();
